import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N = data[0]
    A = data[1:]

    factors = []
    primes = set()
    for x in A:
        d = {}
        q = x
        p = 2
        while p * p <= q:
            while q % p == 0:
                d[p] = d.get(p, 0) + 1
                q //= p
            p += 1
        if q > 1:
            d[q] = d.get(q, 0) + 1
        factors.append(d)
        primes.update(d)

    answer = 1
    for prime in primes:
        steps = [d.get(prime, 0) for d in factors]
        limit = sum(steps)

        prime_pow = [1] * (limit + 1)
        for e in range(1, limit + 1):
            prime_pow[e] = prime_pow[e - 1] * prime % MOD

        # z: paths which have visited height 0; nz: paths which have not.
        z = [0] * (limit + 1)
        nz = [0] * (limit + 1)
        z[0] = 1
        for e in range(1, limit + 1):
            nz[e] = prime_pow[e]

        for step in steps:
            new_z = [0] * (limit + 1)
            new_nz = [0] * (limit + 1)
            for e in range(limit + 1):
                targets = (e,) if step == 0 else (e - step, e + step)
                for ne in targets:
                    if 0 <= ne <= limit:
                        weight = prime_pow[ne]
                        if z[e]:
                            new_z[ne] = (new_z[ne] + z[e] * weight) % MOD
                        if nz[e]:
                            if ne == 0:
                                new_z[ne] = (new_z[ne] + nz[e] * weight) % MOD
                            else:
                                new_nz[ne] = (new_nz[ne] + nz[e] * weight) % MOD
            z, nz = new_z, new_nz

        answer = answer * (sum(z) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

