import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    arr = data[1:1+n]
    limit = max(arr)
    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, limit + 1, p):
                if spf[x] == x:
                    spf[x] = p
    nim = 0
    for a in arr:
        omega = 0
        while a > 1:
            omega += 1
            a //= spf[a]
        nim ^= omega
    print('Anna' if nim else 'Bruno')

if __name__ == '__main__':
    main()

