from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, i))

        largest = second_largest = 0
        largest_id = -1
        gains = [0] * len(conflictingPairs)
        baseline = 0

        for right in range(1, n + 1):
            for left, idx in by_right[right]:
                if left > largest:
                    second_largest = largest
                    largest = left
                    largest_id = idx
                elif left > second_largest:
                    second_largest = left

            baseline += right - largest
            if largest_id != -1:
                gains[largest_id] += largest - second_largest

        return baseline + max(gains)

