import sys

def main():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())
    roads = [None] * M
    for i in range(M):
        a, b, c = map(int, input().split())
        roads[i] = (a-1, b-1, c)

    queries = []
    closed = [False] * M
    for _ in range(Q):
        q = list(map(int, input().split()))
        if q[0] == 1:
            idx = q[1] - 1
            closed[idx] = True
            queries.append((1, idx))
        else:
            queries.append((2, q[1] - 1, q[2] - 1))

    INF = 10**30
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0
    for i, (u, v, w) in enumerate(roads):
        if not closed[i]:
            dist[u][v] = dist[v][u] = w

    # All-pairs shortest paths in the graph after every deletion.
    for k in range(N):
        row_k = dist[k]
        for i in range(N):
            to_k = dist[i][k]
            if to_k == INF:
                continue
            row_i = dist[i]
            for j in range(N):
                candidate = to_k + row_k[j]
                if candidate < row_i[j]:
                    row_i[j] = candidate

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            value = dist[query[1]][query[2]]
            answers.append(str(-1 if value == INF else value))
        else:
            u, v, w = roads[query[1]]
            to_u = [dist[i][u] for i in range(N)]
            to_v = [dist[i][v] for i in range(N)]
            row_u = dist[u][:]
            row_v = dist[v][:]
            for i in range(N):
                a, b = to_u[i], to_v[i]
                if a == INF and b == INF:
                    continue
                row_i = dist[i]
                via_u = a + w if a < INF else INF
                via_v = b + w if b < INF else INF
                for j in range(N):
                    candidate = min(via_u + row_v[j], via_v + row_u[j])
                    if candidate < row_i[j]:
                        row_i[j] = candidate

    print('\n'.join(reversed(answers)))

if __name__ == '__main__':
    main()

