def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    processes = []

    for i in range(n):
        a, p, b, q = data[2 + 4 * i: 6 + 4 * i]
        g = math.gcd(a, b)
        if p * b <= q * a:
            # S has the lower (or equal) cost per unit of capacity.
            # Enumerate fewer than a/g copies of the less efficient T machine.
