class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)

        # steps[x] is the number of popcount operations needed to reach 1.
        steps = [0] * (L + 1)
        for x in range(2, L + 1):
            steps[x] = 1 + steps[x.bit_count()]

        # Binomial coefficients modulo MOD.
        comb = [[0] * (L + 1) for _ in range(L + 1)]
        for a in range(L + 1):
            comb[a][0] = comb[a][a] = 1
            for b in range(1, a):
                comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD

        ans = 0
        prefix_ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                remaining = L - i - 1
                # Numbers first differing from n here have a 0 at this bit.
                for total_ones in range(1, L + 1):
                    if steps[total_ones] <= k - 1:
                        need = total_ones - prefix_ones
                        if 0 <= need <= remaining:
                            ans += comb[remaining][need]
                prefix_ones += 1

        return ans % MOD

