import sys
import heapq

def main():
    input = sys.stdin.readline
    n = int(input())
    g = [input().strip() for _ in range(n)]

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    pq = []

    for i in range(n):
        dist[i][i] = 0
        heapq.heappush(pq, (0, i, i))
        for j, ch in enumerate(g[i]):
            if ch != '-':
                c = ord(ch) - ord('a')
                outgoing[i][c].append(j)
                incoming[j][c].append(i)
                if dist[i][j] > 1:
                    dist[i][j] = 1
                    heapq.heappush(pq, (1, i, j))

    # A palindrome with at least two outer characters can be formed by
    # adding matching-labeled edges around a smaller palindromic path.
    while pq:
        d, a, b = heapq.heappop(pq)
        if d != dist[a][b]:
            continue
        nd = d + 2
        for c in range(26):
            for u in incoming[a][c]:
                row = dist[u]
                for v in outgoing[b][c]:
                    if nd < row[v]:
                        row[v] = nd
                        heapq.heappush(pq, (nd, u, v))

    print('\n'.join(' '.join(str(x if x < inf else -1) for x in row) for row in dist))

if __name__ == '__main__':
    main()

