import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, x = data[0], data[1]
    U = data[2::2]
    D = data[3::2]
    sums = [u + d for u, d in zip(U, D)]

    def feasible(h):
        lo = max(0, h - D[0])
        hi = min(U[0], h)
        if lo > hi:
            return False
        for i in range(1, n):
            left = max(0, h - D[i])
            right = min(U[i], h)
            lo = max(left, lo - x)
            hi = min(right, hi + x)
            if lo > hi:
                return False
        return True

    low, high = 0, min(sums)
    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid - 1

    print(sum(sums) - n * low)

if __name__ == '__main__':
    solve()

