    if not data: return
    n,m=data[0],data[1]
    rows=[0]*n
    p=2
    for _ in range(m):
        u,v=data[p]-1,data[p+1]-1; p+=2
        rows[u] |= 1<<v
        rows[v] |= 1<<u
    # RREF over GF(2)
    pivot_cols=[]
    r=0
    for c in range(n):
        sel=next((i for i in range(r,n) if (rows[i]>>c)&1),None)
        if sel is None: continue
        rows[r],rows[sel]=rows[sel],rows[r]
        for i in range(n):
            if i != r and ((rows[i]>>c)&1):
                rows[i] ^= rows[r]
        pivot_cols.append(c)
        r+=1
    pivset=set(pivot_cols)
    basis=[]
    for f in range(n):
        if f in pivset: continue
        vec=1<<f
        for i,c in enumerate(pivot_cols):
            if (rows[i]>>f)&1:
                vec |= 1<<c
        basis.append(vec)
    vals=[0]*n
    for j,vec in enumerate(basis):
        for v in range(n):
            if (vec>>v)&1:
                vals[v] |= 1<<j
    if any(x==0 for x in vals):
        print('No')
    else:
        print('Yes')
