    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = ((1, 1), (1, -1), (-1, -1), (-1, 1))
        size = n * m * 8
        straight = array('H', [0]) * size
        turned = array('H', [0]) * size

        def idx(r, c, d, v):
            return ((r * m + c) * 4 + d) * 2 + v

        orders = []
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            orders.append((d, dr, dc, list(rows), list(cols)))

        # Longest straight continuation from each cell, direction and expected value.
        for d, dr, dc, rows, cols in orders:
            for r in rows:
                for c in cols:
                    for v, value in enumerate((0, 2)):
                        if grid[r][c] != value:
                            continue
                        nr, nc = r + dr, c + dc
                        length = 1
                        if 0 <= nr < n and 0 <= nc < m:
                            length += straight[idx(nr, nc, d, 1 - v)]
                        straight[idx(r, c, d, v)] = length

        # Continuation allowing a clockwise turn at most once.
        for d, dr, dc, rows, cols in orders:
            td = (d + 1) % 4
            tdr, tdc = dirs[td]
            for r in rows:
                for c in cols:
                    for v, value in enumerate((0, 2)):
                        if grid[r][c] != value:
                            continue
                        best = 1
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            best = max(best, 1 + turned[idx(nr, nc, d, 1 - v)])
                        nr, nc = r + tdr, c + tdc
                        if 0 <= nr < n and 0 <= nc < m:
                            best = max(best, 1 + straight[idx(nr, nc, td, 1 - v)])
                        turned[idx(r, c, d, v)] = best

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                answer = max(answer, 1)
                for d, (dr, dc) in enumerate(dirs):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2:
                        answer = max(answer, 1 + turned[idx(nr, nc, d, 1)])
        return answer

