class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # Positional weights modulo k.
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = (powers[i - 1] * 10) % k

        # Choosing digit d at mirrored positions contributes d * coeff[i].
        coeff = []
        for i in range(m):
            j = n - 1 - i
            c = powers[i]
            if j != i:
                c += powers[j]
            coeff.append(c % k)

        # suffix[i] is a bitmask of all residues achievable using
        # choices i through m-1; bit r represents residue r.
        suffix = [0] * (m + 1)
        suffix[m] = 1  # Only residue 0 is achievable with no digits.
        for i in range(m - 1, -1, -1):
            c = coeff[i]
            digits = range(1, 10) if i == 0 else range(10)
            mask = 0
            for residue in range(k):
                if (suffix[i + 1] >> residue) & 1:
                    for digit in digits:
                        mask |= 1 << ((residue + c * digit) % k)
            suffix[i] = mask

        # Greedily maximize each digit from left to right, retaining only
        # choices for which the remaining positions can complete divisibility.
        answer = ['0'] * n
        residue = 0
        for i, c in enumerate(coeff):
            digits = range(9, 0, -1) if i == 0 else range(9, -1, -1)
            for digit in digits:
                new_residue = (residue + c * digit) % k
                needed = (-new_residue) % k
                if (suffix[i + 1] >> needed) & 1:
                    answer[i] = answer[n - 1 - i] = str(digit)
                    residue = new_residue
                    break

        return ''.join(answer)

