from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # nxt[i] is the first index to the right with a value greater than nums[i].
        nxt = [n] * (n + 1)
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                nxt[i] = stack[-1]
            stack.append(i)

        levels = n.bit_length()
        up = [nxt]
        sums = [[0] * (n + 1)]
        for i in range(n):
            sums[0][i] = nums[i] * (nxt[i] - i)

        # Binary lifting over successive prefix-maximum blocks.
        for _ in range(1, levels):
            prev_up = up[-1]
            prev_sum = sums[-1]
            up.append([prev_up[prev_up[i]] for i in range(n + 1)])
            sums.append([prev_sum[i] + prev_sum[prev_up[i]] for i in range(n + 1)])

        prefix = [0] * (n + 1)
        for i, value in enumerate(nums):
            prefix[i + 1] = prefix[i] + value

        def required_operations(left: int, right: int) -> int:
            # Sum of the running maxima over [left, right], then subtract nums' sum.
            pos = left
            raised_sum = 0
            for j in range(levels - 1, -1, -1):
                next_pos = up[j][pos]
                if next_pos <= right:
                    raised_sum += sums[j][pos]
                    pos = next_pos
            raised_sum += nums[pos] * (right - pos + 1)
            return raised_sum - (prefix[right + 1] - prefix[left])

        answer = 0
        for left in range(n):
            lo, hi = left, n
            while lo + 1 < hi:
                mid = (lo + hi) // 2
                if required_operations(left, mid) <= k:
                    lo = mid
                else:
                    hi = mid
            answer += lo - left + 1

        return answer

