from bisect import bisect_left, bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        x = p.index('*')
        y = p.index('*', x + 1)
        parts = (p[:x], p[x + 1:y], p[y + 1:])
        n = len(s)

        def occurrences(t):
            m = len(t)
            if m == 0:
                return list(range(n + 1))
            pi = [0] * m
            k = 0
            for i in range(1, m):
                while k and t[i] != t[k]:
                    k = pi[k - 1]
                if t[i] == t[k]:
                    k += 1
                pi[i] = k
            out = []
            k = 0
            for i, ch in enumerate(s):
                while k and ch != t[k]:
                    k = pi[k - 1]
                if ch == t[k]:
                    k += 1
                if k == m:
                    out.append(i - m + 1)
                    k = pi[k - 1]
            return out

        a, b, c = map(occurrences, parts)
        la, lb, lc = map(len, parts)
        ans = n + 1
        for mid in b:
            ai = bisect_right(a, mid - la) - 1
            ci = bisect_left(c, mid + lb)
            if ai >= 0 and ci < len(c):
                ans = min(ans, c[ci] + lc - a[ai])
        return -1 if ans == n + 1 else ans

