import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        x, y, z = data[p] - 1, data[p + 1] - 1, data[p + 2]
        p += 3
        adj[x].append((y, z))
        adj[y].append((x, z))

    value = [None] * n
    answer = [0] * n
    for start in range(n):
        if value[start] is not None:
            continue
        value[start] = 0
        queue = [start]
        component = []
        for u in queue:
            component.append(u)
            for v, z in adj[u]:
                expected = value[u] ^ z
                if value[v] is None:
                    value[v] = expected
                    queue.append(v)
                elif value[v] != expected:
                    print(-1)
                    return

        base = 0
        size = len(component)
        for bit in range(31):
            ones = sum((value[u] >> bit) & 1 for u in component)
            if ones > size - ones:
                base |= 1 << bit
        for u in component:
            answer[u] = value[u] ^ base

    print(*answer)

if __name__ == '__main__':
    main()

