import sys
from itertools import combinations

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    a = data[2:]

    total_xor = 0
    for value in a:
        total_xor ^= value

    r = min(k, n - k)
    answer = 0

    if r == 0:
        answer = total_xor if k == n else 0
    elif k <= n - k:
        for chosen in combinations(a, k):
            value = 0
            for x in chosen:
                value ^= x
            if value > answer:
                answer = value
    else:
        # XOR of the chosen elements is total XOR XOR excluded XOR.
        for excluded in combinations(a, n - k):
            value = total_xor
            for x in excluded:
                value ^= x
            if value > answer:
                answer = value

    print(answer)

main()

